type Review={confirmation:string;agents:{id:string;name:string;locked:boolean;linked:boolean;version:number;lockedTraits:TraitName[]}[]};
type Team={agents:TeamAgent[];gaps:string[]};
const error=(e:unknown)=>e instanceof Error&&['version_conflict','review_required'].includes(e.message)?'Changed elsewhere. Read it again, then try once more.':e instanceof Error&&e.message==='personality_locked'?'This agent’s personality is locked. Unlock it on the agent’s page first.':'Could not finish this. Read the library again and try once more.';
export function PersonalitySheet({title,children,footer,onClose}:{title:string;children:ReactNode;footer?:ReactNode;onClose:()=>void}){
 const ref=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const el=ref.current;el?.showModal();return()=>el?.close();},[]);
 return <dialog ref={ref} className="personality-sheet" aria-label={title} onCancel={e=>{e.preventDefault();onClose();}}><header><h2>{title}</h2><button type="button" title="Close (Esc)" aria-label="Close" onClick={onClose}><UiIcon name="close" size={16}/></button></header><div className="personality-sheet-body">{children}</div>{footer&&<footer>{footer}</footer>}</dialog>;
}
/** Word for a 0-100 setting, shown next to its percentage. */
const level=(v:number)=>v<34?'Low':v>66?'High':'Balanced';
function Trait({name,p,onChange}:{name:TraitName;p:Profile;onChange:(p:Profile)=>void}){const v=inverse(name)?100-p.traits[name]:p.traits[name];return <label className="personality-trait"><span>{labels[name]}<small>{level(v)} · {v}%</small></span><input type="range" min="0" max="100" step="1" value={v} aria-valuetext={`${level(v)}, ${v}%`} onChange={e=>onChange({...p,traits:{...p.traits,[name]:inverse(name)?100-Number(e.target.value):Number(e.target.value)}})}/></label>;}
export function ProfileEditor({value:p,onChange}:{value:Profile;onChange:(p:Profile)=>void}){
 const temperament=(key:'extraversion'|'emotionalStability',label:string)=><label className="personality-trait"><span>{label}<small>{p.temperament[key]}%</small></span><input type="range" min="0" max="100" step="1" value={p.temperament[key]} aria-label={label} aria-valuetext={`${p.temperament[key]}%`} onChange={e=>onChange({...p,temperament:{...p.temperament,[key]:Number(e.target.value)}})}/></label>;
 const select=(key:'pace'|'formality'|'humour',label:string,options:string[])=><label>{label}<select value={p[key]} onChange={e=>onChange({...p,[key]:e.target.value})}>{options.map(o=><option value={o} key={o}>{o[0].toUpperCase()+o.slice(1)}</option>)}</select></label>;
 return <div className="personality-simple-editor"><div className="personality-trait-grid">
 {temperament('extraversion','Social energy')}{temperament('emotionalStability','Emotional stability')}
 {(['warmth','curiosity','thoroughness','independence'] as TraitName[]).map(n=><Trait key={n} name={n} p={p} onChange={onChange}/>)}
 </div><details className="personality-advanced"><summary>More settings</summary><div className="personality-trait-grid">{(['creativity','caution','doubt','persistence','verbosity'] as TraitName[]).map(n=><Trait key={n} name={n} p={p} onChange={onChange}/>)}</div><div className="personality-option-grid">{select('pace','Pace',['deliberate','balanced','fast'])}{select('formality','Formality',['casual','neutral','formal'])}{select('humour','Humour',['off','light','playful'])}<label>Language and dialect<select value={p.dialect} onChange={e=>onChange({...p,dialect:e.target.value})}>{allDialects.map(d=><option value={d} key={d}>{dialectLabel[d]}</option>)}</select></label></div><details><summary>Guidelines</summary>{(['do','never','ask'] as const).map(k=><label key={k}>{k==='do'?'Prefer':k==='never'?'Avoid':'When to ask'}<textarea rows={2} maxLength={2000} value={p.principles[k]} onChange={e=>onChange({...p,principles:{...p.principles,[k]:e.target.value}})}/></label>)}<p className="fine-print">Personality changes style, never skills or permissions.</p></details></details></div>;
}
/** Face picker used by hiring and the company wizard: the chosen face and name; a click shows every face. */
export function PersonalityPicker({client,value,onPick,disabled=false,autoPick=true,defaultId='temperament-balanced'}:{client:SessionClient;value?:{id:string;revision:number};onPick:(e:Entry)=>void;disabled?:boolean;autoPick?:boolean;defaultId?:string}){
 const [entries,setEntries]=useState<Entry[]>([]),[notice,setNotice]=useState(''),[attempt,setAttempt]=useState(0),[open,setOpen]=useState(false);
 useEffect(()=>{let live=true;void rpc<{personalities:Entry[]}>(client,'GET',P).then(r=>{if(!live)return;const all=r.personalities.filter(e=>!e.archived);setEntries(all);setNotice('');if(autoPick&&!value){const e=all.find(e=>e.id===defaultId);if(e)onPick(e);}}).catch(()=>{if(live)setNotice('Personality library unavailable. Reload before hiring.');});return()=>{live=false;};},[client,defaultId,autoPick,attempt]);
 const chosen=entries.find(e=>e.id===value?.id);
 return <div className="pl-picker"><span className="pl-picker-label">Personality</span><button type="button" data-popover-anchor className="pl-picker-button" aria-haspopup="dialog" aria-expanded={open} aria-label={`Personality: ${chosen?.profile.name??'not chosen'}`} disabled={disabled||!entries.length} onClick={()=>setOpen(!open)}>{chosen?<PersonalityMark profile={chosen.profile} size={20}/>:<UiIcon name="smile" size={16}/>}<span className="pl-picker-name" dir="auto">{chosen?.profile.name??'Choose a personality'}</span><UiIcon name="chevron" size={12}/></button>
 <Popover open={open} wide label="Choose a personality" onClose={()=>setOpen(false)}><div className="pl-picker-faces" role="radiogroup" aria-label="Personality">{entries.map(e=><button type="button" role="radio" key={e.id} aria-checked={value?.id===e.id} title={e.profile.description} onClick={()=>{onPick(e);setOpen(false);}}><PersonalityMark profile={e.profile} size={26}/><span dir="auto">{e.profile.name}</span></button>)}</div></Popover>
 <small>{notice||chosen?.profile.description||'Choose a saved personality. Change its settings in Personalities.'}</small>{notice&&<button type="button" disabled={disabled} onClick={()=>setAttempt(n=>n+1)}>Reload personalities</button>}</div>;
}

/* ── Personalities as a desktop window (boards PL1–PL4, checklist PL6) ── */
export type Place='all'|'team'|'mine'|'balance'|'archived';
export type Part='character'|'speaking'|'guidelines'|'about'|'try'|'agents'|'versions';
export type SliderKey='extraversion'|'emotionalStability'|TraitName;
export const places:{id:Place;name:string;icon:UiIconName;group?:string}[]=[{id:'all',name:'All personalities',icon:'smile'},{id:'team',name:'In my team',icon:'users'},{id:'mine',name:'Made by me',icon:'pencil'},{id:'balance',name:'Team balance',icon:'scale',group:'Team'},{id:'archived',name:'Archived',icon:'archive',group:'Also'}];
export const parts:{id:Part;name:string;icon:UiIconName}[]=[{id:'character',name:'Character',icon:'sliders'},{id:'speaking',name:'Speaking',icon:'mic'},{id:'guidelines',name:'Guidelines',icon:'note'},{id:'about',name:'About',icon:'info'},{id:'try',name:'Try it',icon:'flask'},{id:'agents',name:'Agents',icon:'users'},{id:'versions',name:'Versions',icon:'history'}];
/** Every slider with the words at its two ends; reply length lives in Speaking, the other ten in Character. */
export const sliderInfo:Record<SliderKey,{name:string;low:string;high:string}>={extraversion:{name:'Social energy',low:'Quiet',high:'Outgoing'},emotionalStability:{name:'Emotional stability',low:'Sensitive',high:'Steady'},warmth:{name:labels.warmth,low:'Reserved',high:'Warm'},curiosity:{name:labels.curiosity,low:'Focused',high:'Curious'},thoroughness:{name:labels.thoroughness,low:'Quick',high:'Thorough'},independence:{name:labels.independence,low:'Asks often',high:'Decides alone'},creativity:{name:labels.creativity,low:'Proven',high:'Inventive'},caution:{name:labels.caution,low:'Bold',high:'Careful'},doubt:{name:labels.doubt,low:'Unsure',high:'Sure'},persistence:{name:labels.persistence,low:'Lets go',high:'Keeps going'},verbosity:{name:labels.verbosity,low:'Short',high:'Long'}};
export const characterKeys:SliderKey[]=['extraversion','emotionalStability','warmth','curiosity','thoroughness','independence','creativity','caution','doubt','persistence'];
export const sliderValue=(p:Profile,k:SliderKey)=>k==='extraversion'||k==='emotionalStability'?p.temperament[k]:inverse(k)?100-p.traits[k]:p.traits[k];
export const withSlider=(p:Profile,k:SliderKey,v:number):Profile=>k==='extraversion'||k==='emotionalStability'?{...p,temperament:{...p.temperament,[k]:v}}:{...p,traits:{...p.traits,[k]:inverse(k)?100-v:v}};
/** Which agents a place shows. "Made by me" are the ones not shipped with Girru. */
export function inPlace(e:Entry,place:Place,query=''){const q=query.trim().toLowerCase();if(q&&!`${e.profile.name} ${e.profile.description}`.toLowerCase().includes(q))return false;return place==='archived'?e.archived:!e.archived&&(place==='team'?(e.usedBy??0)>0:place==='mine'?e.starter===false:true);}
/** The face drawn for a personality: its traits pick the expression, its name the colour. */
export function faceIcon(p:Profile):UiIconName{return p.temperament.emotionalStability>=70&&p.temperament.extraversion<50?'face-calm':p.traits.creativity>=70||p.traits.curiosity>=75?'face-curious':100-p.traits.doubt>=65&&p.temperament.extraversion>=55?'face-bold':'smile';}
export function PersonalityMark({profile,size=34}:{profile?:Profile|null;size?:number}){const c=personalityColour(profile?.name);return <span className="pl-face" aria-hidden="true" style={{inlineSize:size,blockSize:size,color:c,background:`${c}22`,boxShadow:`inset 0 0 0 1.5px ${c}66`}}><UiIcon name={profile?faceIcon(profile):'smile'} size={Math.round(size*.56)}/></span>;}
/** A small picture of five traits instead of numbers. */
export const pictureKeys:SliderKey[]=['extraversion','warmth','curiosity','thoroughness','independence'];
function TraitPicture({profile}:{profile:Profile}){const c=personalityColour(profile.name);return <span className="pl-picture" aria-hidden="true">{pictureKeys.map(k=><i key={k} style={{blockSize:Math.max(3,Math.round(sliderValue(profile,k)/100*22)),background:c}}/>)}</span>;}
/** How an agent prefers to work, for the team balance view. */
export const workStyle=(t:Record<TraitName,number>)=>t.thoroughness>=75?'thorough':t.creativity>=75?'inventive':'balanced';
const gapAdvice:Record<string,{text:string;names:string[]}>={'No careful reviewer':{text:'Nobody on the team checks things carefully. A Cautious or Orderly personality could help.',names:['Cautious','Orderly']},'No strong creative explorer':{text:'Nobody on the team is inventive. A Curious or Playful personality could help with new ideas.',names:['Curious','Playful']},'No especially warm communicator':{text:'Nobody on the team is especially warm. A Warm or Patient personality could help.',names:['Warm','Patient']}};
const same=(a:unknown,b:unknown)=>JSON.stringify(a)===JSON.stringify(b);
const plural=(n:number,one:string)=>`${n} ${one}${n===1?'':'s'}`;
/** Drag data for an agent dragged from Team balance onto a personality in the sidebar. */
export const AGENT_DRAG='application/x-dpro-agent';
const typing=(t:EventTarget|null)=>t instanceof HTMLElement&&!!t.closest('input,textarea,select,[contenteditable=true]');

/** One slider with the words at its ends. `mark` draws a small tick at another value (the library's, on an agent's page). */
export function Slider({k,p,onChange,mark,markName}:{k:SliderKey;p:Profile;onChange:(p:Profile)=>void;mark?:number;markName?:string}){const v=sliderValue(p,k),s=sliderInfo[k];const input=<input type="range" min="0" max="100" step="1" value={v} aria-label={s.name} aria-valuetext={`${level(v)}, ${v}%${mark===undefined?'':`; ${markName??'library'} ${mark}%`}`} onChange={e=>onChange(withSlider(p,k,Number(e.target.value)))}/>;
 return <label className="pl-slider" title={mark===undefined?undefined:`${markName??'Library'}: ${mark}%`}><span className="pl-slider-head"><b>{s.name}</b><small>{level(v)} · {v}%</small></span>{mark===undefined?input:<span className="pl-track">{input}<i className="pl-mark" aria-hidden="true" style={{insetInlineStart:`calc(7px + (100% - 14px) * ${mark/100})`}}/></span>}<span className="pl-ends"><small>{s.low}</small><small>{s.high}</small></span></label>;}
function Choice<T extends string>({label,value,options,onChange}:{label:string;value:T;options:T[];onChange:(v:T)=>void}){return <div className="pl-field"><span>{label}</span><div className="pl-seg" role="radiogroup" aria-label={label}>{options.map(o=><button type="button" role="radio" key={o} aria-checked={value===o} onClick={()=>onChange(o)}>{o[0].toUpperCase()+o.slice(1)}</button>)}</div></div>;}
/** PL2 Character: the name in place, one line, and all ten character sliders on one page. */
export function CharacterPart({p,onChange}:{p:Profile;onChange:(p:Profile)=>void}){return <div className="pl-part"><input className="pl-name" aria-label="Name" maxLength={80} dir="auto" value={p.name} onChange={e=>onChange({...p,name:e.target.value})}/><label className="pl-field"><span>In one line</span><input maxLength={1000} dir="auto" value={p.description} placeholder="How it comes across, in a few words" onChange={e=>onChange({...p,description:e.target.value})}/></label><div className="pl-sliders">{characterKeys.map(k=><Slider key={k} k={k} p={p} onChange={onChange}/>)}</div><p className="pl-fine">A personality changes how an agent talks, never its skills or permissions.</p></div>;}
/** PL2 Speaking: pace, formality, humour, how senior it sounds, language and dialect, reply length. */
export function SpeakingPart({p,onChange}:{p:Profile;onChange:(p:Profile)=>void}){return <div className="pl-part"><Choice label="Pace" value={p.pace} options={['deliberate','balanced','fast']} onChange={v=>onChange({...p,pace:v})}/><Choice label="Formality" value={p.formality} options={['casual','neutral','formal']} onChange={v=>onChange({...p,formality:v})}/><Choice label="Humour" value={p.humour} options={['off','light','playful']} onChange={v=>onChange({...p,humour:v})}/><Choice label="Sounds like" value={p.seniority} options={['junior','senior','lead']} onChange={v=>onChange({...p,seniority:v})}/><p className="pl-fine">How senior it sounds changes the tone only, never rank or permissions.</p><label className="pl-field"><span>Language and dialect</span><select value={p.dialect} onChange={e=>onChange({...p,dialect:e.target.value})}>{allDialects.map(d=><option value={d} key={d}>{dialectLabel[d]}</option>)}</select></label><div className="pl-sliders"><Slider k="verbosity" p={p} onChange={onChange}/></div></div>;}
const guideNames={do:'Prefer',never:'Avoid',ask:'When to ask'} as const;
/** PL2 Guidelines: three long texts, edited in the shared long-text editor. */
export function GuidelinesPart({p,onChange}:{p:Profile;onChange:(p:Profile)=>void}){const [editing,setEditing]=useState<{do:string;never:string;ask:string}|null>(null),[first,setFirst]=useState<'do'|'never'|'ask'>('do');
 return <div className="pl-part">{(['do','never','ask'] as const).map(k=><div className="pl-field" key={k}><span>{guideNames[k]}</span><button type="button" className="pl-longtext" title="Open the long-text editor" onClick={()=>{setFirst(k);setEditing({...p.principles});}}><span dir="auto">{p.principles[k]||'Nothing yet. Click to write.'}</span></button></div>)}<p className="pl-fine">Guidelines change how it talks and when it stops to ask. They never grant tools or permissions.</p>
 {editing&&<DocumentEditor title={`${p.name} · Guidelines`} files={[first,...(['do','never','ask'] as const).filter(k=>k!==first)].map(k=>({id:k,name:`${guideNames[k]}.md`,content:editing[k]}))} maxLength={2000} onChange={(id,text)=>setEditing(g=>g&&{...g,[id]:text})} onClose={()=>{const g=editing;setEditing(null);if(!same(g,p.principles))onChange({...p,principles:g});}}/>}</div>;}
/** PL2 About: style, strengths, things to watch, works well for, less suited to, example replies. */
const aboutNames={archetype:'Style',strengths:'Strengths',blindSpots:'Things to watch',bestFor:'Works well for',notFor:'Less suited to'} as const;
function AboutPart({p,onChange}:{p:Profile;onChange:(p:Profile)=>void}){const names=aboutNames;
 return <div className="pl-part">{(Object.keys(names) as (keyof typeof names)[]).map(k=><label className="pl-field" key={k}><span>{names[k]}</span><input maxLength={1000} dir="auto" value={p[k]} onChange={e=>onChange({...p,[k]:e.target.value})}/></label>)}<div className="pl-field"><span>Example replies</span>{[0,1,2].map(i=><textarea key={i} rows={2} maxLength={1500} dir="auto" aria-label={`Example reply ${i+1}`} value={p.samples[i]??''} onChange={e=>{const s=[0,1,2].map(j=>j===i?e.target.value:p.samples[j]??'');while(s.length&&!s[s.length-1])s.pop();onChange({...p,samples:s});}}/>)}</div></div>;}
/** "How it sounds" and Try it: one reply from the local model only (no tools, memory or paid calls, no fallback). */
export function HowItSounds({client,tryId,profile,compact=false}:{client:SessionClient;tryId:string|null;profile:Profile;compact?:boolean}){
 const [prompt,setPrompt]=useState('A first approach failed. What would you do next?'),[reply,setReply]=useState(''),[note,setNote]=useState(''),[busy,setBusy]=useState(false),[asking,setAsking]=useState(!compact);const asked=useRef(false),live=useRef(true),input=useRef<HTMLInputElement>(null);
 useEffect(()=>()=>{live.current=false;},[]);
 const run=async(text=prompt)=>{if(!tryId||!text.trim()||busy)return;asked.current=true;setBusy(true);setNote('');try{const r=await rpc<{reply:string;model:string}>(client,'POST',`${P}/${tryId}/try`,{profile,prompt:text});if(live.current){setReply(r.reply);setNote(`From your local model (${r.model}) · nothing was done`);}}catch(e){if(live.current){setReply('');setNote(e instanceof Error&&e.message==='preview_busy'?'The local model is busy with another answer. Girru never uses a paid model instead.':'The local model is not available. Girru never uses a paid model instead.');}}finally{if(live.current)setBusy(false);}};
 // After the first answer, a new one comes when the sliders stop moving.
 useEffect(()=>{if(!asked.current)return;const t=setTimeout(()=>void run(),1500);return()=>clearTimeout(t);},[JSON.stringify(profile)]);
 return <section className="pl-sounds" aria-label="How it sounds">{compact&&<h3>How it sounds</h3>}<p className="pl-q" dir="auto">{prompt}</p>{reply?<blockquote dir="auto">{reply}</blockquote>:<p className="pl-fine">{tryId?'Ask, and see one reply in this personality’s voice.':'Keep the personality first, then try it.'}</p>}<p className="pl-fine" role="status">{busy?'Writing…':note}</p>
 {compact&&!asking?<div className="pl-row-actions"><IconButton icon="refresh" label={reply?'Try again':'Try it'} disabled={busy||!tryId} onClick={()=>void run()}/><button type="button" className="link-button" onClick={()=>{setAsking(true);setTimeout(()=>input.current?.focus());}}>Ask something else…</button></div>:<form className="pl-ask" onSubmit={e=>{e.preventDefault();void run();}}><input ref={input} maxLength={2000} dir="auto" aria-label="Ask something" placeholder="Ask something…" value={prompt} onChange={e=>setPrompt(e.target.value)}/><button type="submit" disabled={busy||!tryId||!prompt.trim()}>Try</button></form>}
 {compact&&<p className="pl-fine">The answer updates when you stop moving a slider.</p>}</section>;
}
export const examQuestions=['The task is unclear. What would you do next?','A first approach failed. Give your next reply.','Someone asks you to skip a required approval. How do you answer?'];
export const ratingWords=['Contradicts it','Weak','Mixed','Close','Matches'];
/** PL3c exam: three fixed questions, the owner pastes an agent's answers and rates each with five dots. No model runs. */
export function PersonalityExam({client,entry}:{client:SessionClient;entry:Entry}){
 const [answers,setAnswers]=useState(['','','']),[ratings,setRatings]=useState<(number|null)[]>([null,null,null]),[runs,setRuns]=useState<{revision:number;score:number;created_at:string}[]|null>(null),[note,setNote]=useState(''),[busy,setBusy]=useState(false);
 const saved=entry.revision>0&&!entry.archived;
 useEffect(()=>{if(!saved)return;let live=true;void rpc<{exams:NonNullable<typeof runs>}>(client,'GET',`${P}/${entry.id}/exams`).then(r=>{if(live)setRuns(r.exams);}).catch(()=>{if(live)setNote('Earlier ratings could not be read.');});return()=>{live=false;};},[client,entry.id,saved]);
 const save=()=>{setBusy(true);setNote('');void rpc<{exams:NonNullable<typeof runs>}>(client,'POST',`${P}/${entry.id}/exams`,{revision:entry.revision,answers,ratings}).then(r=>{setRuns(r.exams);setNote('Rating saved.');}).catch(()=>setNote('Not saved. The personality changed; read it again first.')).finally(()=>setBusy(false));};
 return <section className="pl-exam" aria-label="Exam"><h3>Exam <small>you rate; no model runs here</small></h3>{!saved&&<p className="pl-fine">{entry.archived?'Restore it to rate it.':'Keep the personality first to rate it.'}</p>}
 <fieldset disabled={!saved||busy}>{examQuestions.map((q,i)=><div className="pl-exam-q" key={q}><b>{q}</b><textarea rows={2} maxLength={4000} dir="auto" aria-label={`Answer ${i+1}`} placeholder="Paste the agent’s answer here" value={answers[i]} onChange={e=>setAnswers(answers.map((v,j)=>j===i?e.target.value:v))}/><span className="pl-dots" role="radiogroup" aria-label={`How well answer ${i+1} matches`}>{ratingWords.map((w,n)=><button type="button" role="radio" key={w} title={w} aria-label={w} aria-checked={ratings[i]===n} data-on={ratings[i]!==null&&n<=ratings[i]!||undefined} onClick={()=>setRatings(ratings.map((v,j)=>j===i?n:v))}/>)}<small>{ratings[i]===null?'Not rated':ratingWords[ratings[i]!]}</small></span></div>)}</fieldset>
 <p className="pl-fine">Never rate skipping an approval as a match.</p>
 <div className="pl-row-actions"><small className="pl-earlier">{runs?.length?`Earlier: ${runs.slice(0,3).map(r=>`version ${r.revision} · ${r.score} of 100`).join(' · ')}`:'No earlier ratings'}</small><span role="status" className="pl-fine">{note}</span><button type="button" disabled={!saved||busy||answers.some(a=>!a.trim())||ratings.some(r=>r===null)} onClick={save}>Save the rating</button></div></section>;
}

type Draft={entry:Entry;profile:Profile;history:Profile[];review:boolean;saving:boolean};
type SheetState={kind:'new';from?:string}|{kind:'review';data:Review}|{kind:'give';entry:Entry}|{kind:'change';agent:TeamAgent};
/**
 * The Personalities section: places in the sidebar (PL1, PL4), a personality opened into its parts (PL2),
 * sheets for new / linked update / give (PL3). Edits to a personality nobody follows save by themselves;
 * one that agents follow keeps a draft until "Update N agents" is confirmed here by the owner.
 */
export function PersonalityLibrary({client,sidebarSlot,active=true,onOpenAgent}:{client:SessionClient;sidebarSlot?:HTMLElement|null;active?:boolean;onOpenAgent?:(agentId:string)=>void}){
 const [entries,setEntries]=useState<Entry[]>([]),[team,setTeam]=useState<Team|null>(null),[phase,setPhase]=useState<'loading'|'ready'|'error'>('loading'),[reload,setReload]=useState(0);
 const [place,setPlace]=useState<Place>('all'),[query,setQuery]=useState(''),[selectedId,setSelectedId]=useState<string|null>(null),[view,setView]=useState<'library'|'open'>('library'),[part,setPart]=useState<Part>('character');
 const [draft,setDraft]=useState<Draft|null>(null),[sheet,setSheet]=useState<SheetState|null>(null),[busy,setBusy]=useState(false),[problem,setProblem]=useState(''),[inspector,setInspector]=useState(true),[department,setDepartment]=useState('all');
 const [toast,setToast]=useState<{id:number;text:string;undo:boolean}|null>(null),[dropOn,setDropOn]=useState<string|null>(null);const undoRef=useRef<(()=>Promise<void>)|null>(null),lastPush=useRef(0),draftRef=useRef(draft),search=useRef<HTMLInputElement>(null),list=useRef<HTMLDivElement>(null);draftRef.current=draft;
 const menu=useMenu();
 useEffect(()=>{if(!active)return;let live=true;void Promise.all([rpc<{personalities:Entry[]}>(client,'GET',P),rpc<Team>(client,'GET',P+'/team').catch(()=>null)]).then(([l,t])=>{if(!live)return;setEntries(l.personalities);rememberLibrary(client,l.personalities);setTeam(t);setPhase('ready');setProblem('');setDraft(d=>{if(!d||d.entry.revision===0)return d;const e=l.personalities.find(x=>x.id===d.entry.id);return e?{...d,entry:{...d.entry,...e}}:d;});}).catch(()=>{if(live){setPhase('error');setProblem('The personality library could not be read.');}});return()=>{live=false;};},[client,active,reload]);
 const say=(text:string,undo?:()=>Promise<void>)=>{undoRef.current=undo??null;setToast({id:Date.now(),text,undo:!!undo});};
 const act=async(fn:()=>Promise<void>)=>{if(busy)return;setBusy(true);setProblem('');try{await fn();}catch(e){setProblem(error(e));}finally{setBusy(false);}};
 const shown=entries.filter(e=>inPlace(e,place,query)).sort((a,b)=>a.profile.name.localeCompare(b.profile.name));
 const selected=shown.find(e=>e.id===selectedId)??shown[0]??null;
 const followers=(id:string)=>team?team.agents.filter(a=>a.personalityId===id&&a.linked):null;
 const dirty=!!draft&&!same(draft.profile,draft.entry.profile);
 const pending=(d:Draft|null)=>!!d&&(d.entry.revision===0||d.review&&!same(d.profile,d.entry.profile));
 const byId=(id:string|null)=>entries.find(e=>e.id===id);

 function openEntry(e:Entry,to:Part='character'){if(draft&&draft.entry.id!==e.id&&pending(draft)){say(`Finish “${draft.profile.name}” first: keep it, update its agents or throw the draft away.`);setView('open');return;}
  if(!draft||draft.entry.id!==e.id)setDraft({entry:e,profile:structuredClone(e.profile),history:[],review:(followers(e.id)?.length??0)>0,saving:false});setSelectedId(e.id);setPart(to);setView('open');}
 function close(){setView('library');if(draft&&!pending(draft))setDraft(null);setTimeout(()=>list.current?.querySelector<HTMLElement>('[aria-current=true]')?.focus());}
 function edit(p:Profile){setDraft(d=>{if(!d)return d;const now=Date.now(),push=now-lastPush.current>700;lastPush.current=now;return {...d,profile:p,history:push?[...d.history.slice(-49),d.profile]:d.history};});}
 // Save by itself: only a kept personality that no agent follows. A linked one waits for the owner's review.
 useEffect(()=>{const d=draft;if(!d||d.entry.revision===0||d.review||d.saving||same(d.profile,d.entry.profile)||!d.profile.name.trim()||d.entry.archived)return;const t=setTimeout(()=>void autosave(),1200);return()=>clearTimeout(t);},[draft]);
 async function autosave(){const d=draftRef.current;if(!d)return;const profile=d.profile;setDraft(x=>x&&{...x,saving:true});
  try{const e=await rpc<Entry>(client,'PUT',`${P}/${d.entry.id}`,{revision:d.entry.revision,profile});setDraft(x=>x&&x.entry.id===e.id?{...x,entry:{...x.entry,...e},saving:false}:x);setEntries(l=>l.map(x=>x.id===e.id?{...x,...e}:x));}
  catch(e){setDraft(x=>x&&{...x,saving:false,review:x.review||e instanceof Error&&e.message==='review_required'});if(!(e instanceof Error&&e.message==='review_required'))setProblem(error(e));}}
 const keep=()=>act(async()=>{const d=draft;if(!d)return;const e=await rpc<Entry>(client,'PUT',`${P}/${d.entry.id}`,{revision:0,profile:d.profile});const full={...e,usedBy:0,starter:false,agents:[]};setEntries(l=>[...l,full]);setDraft({entry:full,profile:structuredClone(full.profile),history:[],review:false,saving:false});say(`Kept “${e.profile.name}”. You can give it to agents now.`,async()=>{await rpc(client,'POST',`${P}/${e.id}/archive`,{revision:e.revision,archived:true});setDraft(null);setView('library');setReload(x=>x+1);});});
 const update=()=>act(async()=>{const d=draft;if(!d)return;setSheet({kind:'review',data:await rpc<Review>(client,'POST',`${P}/${d.entry.id}/preview`,{revision:d.entry.revision,profile:d.profile})});});
 const confirm=(r:Review)=>act(async()=>{const d=draft;if(!d)return;const e=await rpc<Entry>(client,'PUT',`${P}/${d.entry.id}`,{revision:d.entry.revision,profile:d.profile,confirmation:r.confirmation});const n=r.agents.filter(a=>a.linked&&!a.locked).length;setDraft(x=>x&&{...x,entry:{...x.entry,...e},history:[]});setSheet(null);setReload(x=>x+1);say(`Updated ${plural(n,'agent')}. They get it on their next turn.`);});
 const throwAway=()=>{const d=draft;if(!d)return;if(d.entry.revision===0){setDraft(null);setView('library');say('Draft thrown away.');return;}setDraft({...d,profile:structuredClone(d.entry.profile),history:[]});say('Draft thrown away.');};
 const archive=(e:Entry)=>act(async()=>{await rpc(client,'POST',`${P}/${e.id}/archive`,{revision:e.revision,archived:!e.archived});if(draft?.entry.id===e.id){setDraft(null);setView('library');}setReload(x=>x+1);say(e.archived?`Restored “${e.profile.name}”.`:`Archived “${e.profile.name}”. Agents that have it keep it.`,async()=>{await rpc(client,'POST',`${P}/${e.id}/archive`,{revision:e.revision,archived:e.archived});setReload(x=>x+1);});});
 const give=(agent:TeamAgent,e:Entry)=>act(async()=>{const before=byId(agent.personalityId);const r=await rpc<{version:number}>(client,'POST',`${P}/assigned/${agent.id}`,{id:e.id,revision:e.revision,expectedVersion:agent.version??0,linked:agent.personalityId?agent.linked:true});setSheet(null);setReload(x=>x+1);
  say(`${agent.name} now has “${e.profile.name}”.`,before&&!before.archived?async()=>{await rpc(client,'POST',`${P}/assigned/${agent.id}`,{id:before.id,revision:before.revision,expectedVersion:r.version,linked:agent.linked});setReload(x=>x+1);}:undefined);});
 // Team balance: an agent dropped on a personality gets it, with the same Undo as the Change sheet.
 const dropAgent=(id:string,e:Entry)=>{const a=team?.agents.find(x=>x.id===id);if(!a)return;if(a.locked){say(`${a.name}’s personality is locked. Unlock it on its page first.`);return;}if(a.personalityId===e.id){say(`${a.name} already has “${e.profile.name}”.`);return;}void give(a,e);};
 const newDraft=(base:Profile)=>{const e:Entry={id:crypto.randomUUID(),revision:0,profile:base,archived:false,usedBy:0,starter:false,agents:[]};setDraft({entry:e,profile:structuredClone(base),history:[],review:false,saving:false});setSheet(null);setPart('character');setView('open');};
 function undo(){if(view==='open'&&draft?.history.length){const prev=draft.history[draft.history.length-1];setDraft({...draft,profile:prev,history:draft.history.slice(0,-1)});return;}runUndo();}
 function runUndo(){const fn=undoRef.current;if(fn){undoRef.current=null;setToast(null);void act(fn);}}
 const startNew=()=>{if(pending(draft)&&draft){say(`Finish “${draft.profile.name}” first: keep it, update its agents or throw the draft away.`);return;}setSheet({kind:'new'});};
 const itemMenu=(e:Entry):MenuItem[]=>[{label:'Open',icon:'open',shortcut:'Enter',run:()=>openEntry(e)},...(e.archived?[]:[{label:'Give to an agent…',icon:'user-give' as UiIconName,shortcut:'⌘G',disabled:!team,run:()=>setSheet({kind:'give',entry:e})},{label:'Copy as a new personality',icon:'copy' as UiIconName,run:()=>{if(!pending(draft))newDraft({...structuredClone(e.profile),name:`${e.profile.name} copy`.slice(0,80)});}},{label:'Versions',icon:'history' as UiIconName,run:()=>openEntry(e,'versions')}]),'sep',{label:e.archived?'Restore':'Archive',icon:'archive',run:()=>void archive(e)}];

 const here=(id:Place)=>view==='library'&&place===id?'page' as const:undefined;
 const sidebar=view==='open'&&draft?<nav className="dk-sidebar pl-places" aria-label={`${draft.profile.name} parts`}>
  <button className="nav-item dk-place" title="All personalities (Esc)" onClick={close}><UiIcon name="arrow-left" size={15}/><span className="dk-place-name">All personalities</span></button>
  <div className="pl-side-head"><PersonalityMark profile={draft.profile} size={30}/><span><b dir="auto">{draft.profile.name||'Unnamed'}</b><small>{draft.entry.revision===0?'Not kept yet':`Used by ${plural(draft.entry.usedBy??0,'agent')}`}</small></span></div>
  {parts.map(x=><button key={x.id} className="nav-item dk-place" aria-current={part===x.id?'page':undefined} onClick={()=>setPart(x.id)}><UiIcon name={x.icon} size={15}/><span className="dk-place-name">{x.name}</span>{x.id==='agents'&&(draft.entry.usedBy??0)>0&&<small className="pl-note">{draft.entry.usedBy}</small>}</button>)}
 </nav>:<nav className="dk-sidebar pl-places" aria-label="Personality places">
  <div className="pl-search-row"><label className="dk-search pl-search"><UiIcon name="search" size={13}/><input ref={search} type="search" aria-label="Search personalities" placeholder="Search  ⌘F" value={query} onChange={e=>{setQuery(e.target.value);if(place==='balance')setPlace('all');}}/></label><IconButton icon="plus" label="New personality" shortcut="⌘N" disabled={busy} onClick={startNew}/></div>
  {places.map((x,i)=><span key={x.id} className="pl-place-wrap">{x.group&&x.group!==places[i-1]?.group&&<p className="section-label dk-label">{x.group}</p>}<button className="nav-item dk-place" aria-current={here(x.id)} onClick={()=>{setPlace(x.id);setView('library');}}><UiIcon name={x.icon} size={15}/><span className="dk-place-name">{x.name}</span></button></span>)}
  {place==='balance'&&team&&<><p className="section-label dk-label">Personalities</p>{entries.filter(e=>!e.archived).sort((a,b)=>a.profile.name.localeCompare(b.profile.name)).map(e=><button key={e.id} className="nav-item dk-place pl-drop" data-over={dropOn===e.id||undefined} title={`Drop an agent here to give it “${e.profile.name}”`} onClick={()=>{setPlace('all');setSelectedId(e.id);}} onDragOver={ev=>{if(!ev.dataTransfer.types.includes(AGENT_DRAG))return;ev.preventDefault();ev.dataTransfer.dropEffect='move';setDropOn(e.id);}} onDragLeave={()=>setDropOn(x=>x===e.id?null:x)} onDrop={ev=>{ev.preventDefault();setDropOn(null);dropAgent(ev.dataTransfer.getData(AGENT_DRAG),e);}}><PersonalityMark profile={e.profile} size={18}/><span className="dk-place-name" dir="auto">{e.profile.name}</span></button>)}</>}
  {draft&&pending(draft)&&<><p className="section-label dk-label">Draft</p><button className="nav-item dk-place" onClick={()=>setView('open')}><PersonalityMark profile={draft.profile} size={18}/><span className="dk-place-name" dir="auto">{draft.profile.name||'Unnamed'}</span></button></>}
 </nav>;

 const keys=(e:KeyEv)=>{if(!active||sheet)return;const mod=e.metaKey||e.ctrlKey,k=e.key.toLowerCase();
  if(mod&&k==='n'){e.preventDefault();startNew();return;}
  if(mod&&k==='f'){e.preventDefault();if(view==='open')close();setTimeout(()=>search.current?.focus());return;}
  if(mod&&k==='z'&&!typing(e.target)){e.preventDefault();undo();return;}
  if(mod&&k==='g'){e.preventDefault();const t=view==='open'?draft?.entry:selected;if(t&&t.revision>0&&!t.archived&&team)setSheet({kind:'give',entry:t});return;}
  if(e.key==='Escape'&&view==='open'&&!typing(e.target)){e.preventDefault();close();}};
 const listKeys=(e:KeyEv)=>{if(!selected)return;const i=shown.findIndex(x=>x.id===selected.id);
  if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?shown.length-1:Math.max(0,Math.min(shown.length-1,i+(e.key==='ArrowDown'?1:-1)));setSelectedId(shown[n].id);setTimeout(()=>document.getElementById(`pl-row-${shown[n].id}`)?.focus());}
  else if(e.key==='Enter'){e.preventDefault();openEntry(selected);}
  else if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10')menu.at(e,itemMenu(selected));
  else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();void archive(selected);}};

 const status=!draft?'':draft.entry.archived?'Archived · restore it to change it':draft.entry.revision===0?'Draft · not kept yet':draft.saving?'Saving…':draft.review&&dirty?'Draft · its agents get it when you update them':dirty?'Saving when you pause…':draft.history.length?'Saved · ⌘Z undoes':'Up to date';
 const linked=draft?followers(draft.entry.id):null,toUpdate=linked?linked.filter(a=>!a.locked).length:null;
 const mainButton=!draft||draft.entry.archived?null:draft.entry.revision===0?<button type="button" className="primary pl-main" disabled={busy||!draft.profile.name.trim()} onClick={()=>void keep()}>Keep this personality</button>:draft.review?<button type="button" className="primary pl-main" disabled={busy||!dirty||!draft.profile.name.trim()} onClick={()=>void update()}>{toUpdate===null?'Update its agents…':`Update ${plural(toUpdate,'agent')}…`}</button>:null;
 const openMenu=(ev:MouseEv)=>{if(!draft)return;const e=draft.entry;menu.at(ev,[...(e.revision>0&&!e.archived?[{label:'Give to an agent…',icon:'user-give' as UiIconName,shortcut:'⌘G',disabled:!team,run:()=>setSheet({kind:'give',entry:e})}]:[]),{label:'Undo',icon:'undo',shortcut:'⌘Z',disabled:!draft.history.length,run:undo},{label:'Throw the draft away',icon:'eraser',disabled:!dirty&&e.revision>0,run:throwAway},...(e.revision>0?['sep' as const,{label:e.archived?'Restore':'Archive',icon:'archive' as UiIconName,run:()=>void archive(e)}]:[])]);};

 const content=view==='open'&&draft?<div className="pl-open" data-sounds={part==='character'||part==='speaking'||undefined}>
  <div className="pl-open-main"><fieldset disabled={busy||draft.entry.archived}>
   {part==='character'&&<CharacterPart p={draft.profile} onChange={edit}/>}
   {part==='speaking'&&<SpeakingPart p={draft.profile} onChange={edit}/>}
   {part==='guidelines'&&<GuidelinesPart p={draft.profile} onChange={edit}/>}
   {part==='about'&&<AboutPart p={draft.profile} onChange={edit}/>}
  </fieldset>
   {part==='try'&&<div className="pl-part"><HowItSounds key={draft.entry.id} client={client} tryId={draft.entry.revision>0?draft.entry.id:entries.find(x=>!x.archived)?.id??null} profile={draft.profile}/><p className="pl-fine">If the local model is busy, Girru says so and never uses a paid model instead.</p><PersonalityExam key={draft.entry.id} client={client} entry={draft.entry}/></div>}
   {part==='agents'&&<AgentsPart entry={draft.entry} team={team} onOpenAgent={onOpenAgent} onChange={a=>setSheet({kind:'change',agent:a})} onGive={draft.entry.revision>0&&!draft.entry.archived&&team?()=>setSheet({kind:'give',entry:draft.entry}):undefined} menu={menu}/>}
   {part==='versions'&&<VersionsPart client={client} entry={draft.entry} disabled={busy||draft.entry.archived} onRestore={p=>{edit(p);setPart('character');say('Version restored as a draft. ⌘Z goes back.');}}/>}
  </div>
  {(part==='character'||part==='speaking')&&<aside className="pl-open-side"><HowItSounds key={draft.entry.id} compact client={client} tryId={draft.entry.revision>0?draft.entry.id:entries.find(x=>!x.archived)?.id??null} profile={draft.profile}/></aside>}
 </div>:place==='balance'?<TeamBalance team={team} entries={entries} department={department} onChange={a=>setSheet({kind:'change',agent:a})} onGive={e=>setSheet({kind:'give',entry:e})} onOpenAgent={onOpenAgent} menu={menu}/>
 :<div className="pl-panes" data-inspector={inspector&&!!selected||undefined}>
  <div ref={list} className="pl-list" role="listbox" aria-label="Personalities" onKeyDown={listKeys}>
   {phase==='loading'&&!entries.length?<p className="pl-empty" role="status">Reading personalities…</p>:!shown.length?<div className="pl-empty"><UiIcon name={places.find(x=>x.id===place)?.icon??'smile'} size={30}/><p>{query?'No personality matches this search.':place==='mine'?'Personalities you make show here.':place==='team'?'No agent has a personality from the library yet.':place==='archived'?'Nothing is archived.':'There are no personalities yet.'}</p>{place!=='archived'&&!query&&<button type="button" onClick={startNew}>New personality</button>}</div>
   :shown.map(e=><button type="button" role="option" id={`pl-row-${e.id}`} key={e.id} className="pl-row" aria-selected={selected?.id===e.id} aria-current={selected?.id===e.id||undefined} tabIndex={selected?.id===e.id?0:-1} onClick={()=>setSelectedId(e.id)} onDoubleClick={()=>openEntry(e)} onContextMenu={ev=>{setSelectedId(e.id);menu.at(ev,itemMenu(e));}}>
    <PersonalityMark profile={e.profile}/><span className="pl-row-text"><b dir="auto">{e.profile.name}</b><small dir="auto">{e.profile.description||'No line yet'}</small></span><TraitPicture profile={e.profile}/><span className="pl-row-agents">{(e.agents??[]).length?<span className="dk-avatars" aria-label={(e.agents??[]).map(a=>a.name).join(', ')}>{(e.agents??[]).slice(0,3).map(a=><Avatar key={a.id} name={a.name} size={20}/>)}{(e.agents??[]).length>3&&<span className="dk-more">+{(e.agents??[]).length-3}</span>}</span>:null}</span></button>)}
  </div>
  {selected&&inspector&&<Inspector entry={selected} team={team} busy={busy} onOpen={()=>openEntry(selected)} onGive={()=>setSheet({kind:'give',entry:selected})} onRestore={()=>void archive(selected)} onMenu={ev=>menu.at(ev,itemMenu(selected))} onClose={()=>setInspector(false)}/>}
 </div>;

 const title=view==='open'&&draft?parts.find(x=>x.id===part)?.name:places.find(x=>x.id===place)?.name;
 return <section className="pl-window" aria-label="Personalities" data-inline-sidebar={!sidebarSlot||undefined} onKeyDown={keys}>
  {active&&sidebarSlot?createPortal(sidebar,sidebarSlot):!sidebarSlot?sidebar:null}
  <div className="pl-main">
   <header className="pl-toolbar">{view==='open'&&draft&&<PersonalityMark profile={draft.profile} size={22}/>}<h2>{title}</h2>{view==='open'&&draft?<><span className="pl-status" role="status">{status}</span>{mainButton}<IconButton icon="more" label="More" onClick={openMenu}/></>:<>{place==='balance'&&team&&<select className="pl-dept" aria-label="Department" value={department} onChange={e=>setDepartment(e.target.value)}><option value="all">All departments</option>{[...new Set(team.agents.map(a=>a.department??''))].sort().map(d=><option key={d} value={d}>{d?d[0].toUpperCase()+d.slice(1):'No department'}</option>)}</select>}{place!=='balance'&&<IconButton icon="sidebar" label={inspector?'Hide details':'Show details'} pressed={inspector} onClick={()=>setInspector(!inspector)}/>}<IconButton icon="more" label="More" onClick={ev=>menu.at(ev,[{label:'New personality',icon:'plus',shortcut:'⌘N',run:startNew},{label:'Undo',icon:'undo',shortcut:'⌘Z',disabled:!undoRef.current,run:undo},{label:'Read the library again',icon:'refresh',run:()=>setReload(x=>x+1)}])}/></>}</header>
   {problem&&<p className="pl-problem" role="alert"><UiIcon name="alert" size={14}/>{problem}<button type="button" className="link-button" disabled={busy} onClick={()=>{setProblem('');setReload(x=>x+1);}}>Read again</button></p>}
   <div className="pl-content">{content}</div>
  </div>
  <ContextMenu menu={menu.menu} onClose={menu.close}/>
  <Notice toast={toast} onUndo={runUndo} onDone={id=>setToast(t=>t?.id===id?null:t)}/>
  {sheet?.kind==='new'&&<NewSheet entries={entries.filter(e=>!e.archived)} busy={busy} onBlend={(a,b,w)=>act(async()=>{newDraft((await rpc<{profile:Profile}>(client,'POST',P+'/blend',{a,b,weight:w})).profile);})} onMake={newDraft} onClose={()=>setSheet(null)}/>}
  {sheet?.kind==='review'&&draft&&<Sheet title={`Update ${draft.entry.profile.name} for the agents that follow it?`} wide onClose={()=>{if(!busy)setSheet(null);}} actions={<><button type="button" disabled={busy} onClick={()=>setSheet(null)}>Keep editing</button><button type="button" className="primary" disabled={busy} onClick={()=>void confirm(sheet.data)}>{`Update ${plural(sheet.data.agents.filter(a=>a.linked&&!a.locked).length,'agent')}`}</button></>}>
   <table className="pl-diff"><thead><tr><th>What</th><th>Now</th><th>After</th></tr></thead><tbody>{profileChanges(draft.entry.profile,draft.profile).map(c=><tr key={c.label}><th scope="row">{c.label}</th><td dir="auto">{c.before}</td><td dir="auto">{c.after}</td></tr>)}</tbody></table>
   <ul className="pl-who">{sheet.data.agents.map(a=><li key={a.id}><Avatar name={a.name} size={22}/><bdi>{a.name}</bdi><span><UiIcon name={a.locked?'lock':!a.linked?'unlink':'check'} size={13}/>{a.locked?'Locked · skipped':!a.linked?'Own copy · unchanged':a.lockedTraits.length?'Gets the change · its locked traits stay':'Gets the change'}</span></li>)}</ul>
   <p className="pl-fine">They get it on their next turn. Each agent’s own adjustments and locked traits stay.</p></Sheet>}
  {sheet?.kind==='give'&&team&&<Sheet title={`Give “${sheet.entry.profile.name}” to an agent`} wide onClose={()=>{if(!busy)setSheet(null);}} actions={<button type="button" onClick={()=>setSheet(null)}>Cancel</button>}>
   <div className="pl-pick" role="list">{team.agents.map(a=>{const has=byId(a.personalityId);return <button type="button" role="listitem" key={a.id} className="pl-pick-row" disabled={busy||a.locked||a.personalityId===sheet.entry.id} onClick={()=>void give(a,sheet.entry)}><Avatar name={a.name} size={26}/><span className="pl-row-text"><b dir="auto">{a.name}</b><small>{a.locked?'Locked · unlock it on its page first':a.personalityId===sheet.entry.id?'Already has it':has?`Now ${has.profile.name}`:'Its own settings'}</small></span>{has&&<PersonalityMark profile={has.profile} size={20}/>}</button>;})}</div>
   <p className="pl-fine">It applies at once; Undo puts the earlier personality back. Agents that follow library changes keep following.</p></Sheet>}
  {sheet?.kind==='change'&&<Sheet title={`Change ${sheet.agent.name}’s personality`} wide onClose={()=>{if(!busy)setSheet(null);}} actions={<button type="button" onClick={()=>setSheet(null)}>Cancel</button>}>
   {sheet.agent.locked?<p>This agent’s personality is locked. Unlock it on its page first.</p>:<div className="ag-faces" role="radiogroup" aria-label="Personality">{entries.filter(e=>!e.archived).map(e=><button type="button" role="radio" aria-checked={sheet.agent.personalityId===e.id} key={e.id} className="ag-face-card" disabled={busy} onClick={()=>{if(sheet.agent.personalityId!==e.id)void give(sheet.agent,e);}}><PersonalityMark profile={e.profile}/><b>{e.profile.name}</b><small dir="auto">{e.profile.description}</small></button>)}</div>}</Sheet>}
 </section>;
}

export function Inspector({entry:e,team,busy,onOpen,onGive,onRestore,onMenu,onClose}:{entry:Entry;team:Team|null;busy:boolean;onOpen:()=>void;onGive:()=>void;onRestore:()=>void;onMenu:(ev:MouseEv)=>void;onClose:()=>void}){
 const p=e.profile,agents=e.agents??[];
 return <aside className="pl-insp" aria-label={`${p.name} details`}>
  <div className="pl-insp-head"><PersonalityMark profile={p} size={48}/><span><b dir="auto">{p.name}</b><small>{e.archived?'Archived':e.starter?`Starter · used by ${plural(e.usedBy??0,'agent')}`:`Used by ${plural(e.usedBy??0,'agent')}`}</small></span><span className="pl-insp-close"><IconButton icon="close" label="Hide details" onClick={onClose}/></span></div>
  {p.description&&<p dir="auto" className="pl-insp-line">{p.description}</p>}
  <div className="pl-insp-actions">{e.archived?<button type="button" className="primary pl-main" disabled={busy} onClick={onRestore}>Restore</button>:<button type="button" className="primary pl-main" disabled={busy||!team} title="Give to an agent (⌘G)" onClick={onGive}>Give to an agent…</button>}<IconButton icon="open" label="Open" shortcut="Enter" onClick={onOpen}/><IconButton icon="more" label="More" onClick={onMenu}/></div>
  <h4>Character</h4><div className="pl-bars">{characterKeys.slice(0,6).map(k=>{const v=sliderValue(p,k);return <div key={k} className="pl-bar"><span>{sliderInfo[k].name}</span><i><b style={{inlineSize:`${v}%`,background:personalityColour(p.name)}}/></i><small>{v}%</small></div>;})}</div>
  <h4>Speaks</h4><div className="pl-chips"><span>{p.pace[0].toUpperCase()+p.pace.slice(1)} pace</span><span>{p.formality[0].toUpperCase()+p.formality.slice(1)}</span><span>{p.humour==='off'?'No humour':`${p.humour[0].toUpperCase()+p.humour.slice(1)} humour`}</span><span>{p.seniority[0].toUpperCase()+p.seniority.slice(1)} voice</span><span>{dialectLabel[p.dialect as keyof typeof dialectLabel]??p.dialect}</span></div>
  <h4>Agents with it</h4>{agents.length?<ul className="pl-agents">{agents.slice(0,8).map(a=><li key={a.id}><Avatar name={a.name} size={20}/><bdi>{a.name}</bdi></li>)}{agents.length>8&&<li className="pl-fine">and {agents.length-8} more</li>}</ul>:<p className="pl-fine">No agent has it yet.</p>}
  <p className="pl-fine">A personality changes how an agent talks, never its skills or permissions.</p>
 </aside>;
}
function AgentsPart({entry,team,onOpenAgent,onChange,onGive,menu}:{entry:Entry;team:Team|null;onOpenAgent?:(id:string)=>void;onChange:(a:TeamAgent)=>void;onGive?:()=>void;menu:ReturnType<typeof useMenu>}){
 const rows=(entry.agents??[]).map(a=>({a,t:team?.agents.find(x=>x.id===a.id)}));
 const items=(id:string,t?:TeamAgent):MenuItem[]=>[...(onOpenAgent?[{label:'Open the agent',icon:'open' as UiIconName,run:()=>onOpenAgent(id)}]:[]),{label:'Change personality…',icon:'smile',disabled:!t||t.locked,run:()=>t&&onChange(t)}];
 return <div className="pl-part">{rows.length?<ul className="pl-agent-rows">{rows.map(({a,t})=><li key={a.id} tabIndex={0} onContextMenu={ev=>menu.at(ev,items(a.id,t))} onKeyDown={ev=>{if(ev.key==='Enter'&&onOpenAgent)onOpenAgent(a.id);if(ev.key==='ContextMenu'||ev.shiftKey&&ev.key==='F10')menu.at(ev,items(a.id,t));}}><Avatar name={a.name} size={26}/><span className="pl-row-text"><b dir="auto">{a.name}</b><small>{!t?'':t.locked?'Locked · gets no changes':t.linked?'Follows library changes':'Own copy · does not follow changes'}</small></span><IconButton icon="more" label={`${a.name}: more`} onClick={ev=>menu.at(ev,items(a.id,t))}/></li>)}</ul>:<p className="pl-empty">No agent has this personality yet.</p>}
  {onGive&&<div className="pl-row-actions"><button type="button" onClick={onGive}>Give to another agent…</button></div>}<p className="pl-fine">Each agent’s own adjustments, lock and versions are on its page.</p></div>;
}
function VersionsPart({client,entry,disabled,onRestore}:{client:SessionClient;entry:Entry;disabled:boolean;onRestore:(p:Profile)=>void}){
 const [rows,setRows]=useState<{revision:number;profile_json:string;created_at:string}[]|null>(null),[failed,setFailed]=useState(false);
 useEffect(()=>{if(entry.revision===0){setRows([]);return;}let live=true;void rpc<{versions:NonNullable<typeof rows>}>(client,'GET',`${P}/${entry.id}/versions`).then(r=>{if(live)setRows(r.versions);}).catch(()=>{if(live)setFailed(true);});return()=>{live=false;};},[client,entry.id,entry.revision]);
 if(failed)return <p className="pl-empty" role="status">The versions could not be read.</p>;if(!rows)return <p className="pl-empty" role="status">Reading versions…</p>;if(!rows.length)return <p className="pl-empty">Versions start when you keep the personality.</p>;
 return <div className="pl-part"><ul className="pl-versions">{rows.map(v=><li key={v.revision} data-current={v.revision===entry.revision||undefined}><UiIcon name="history" size={14}/><span className="pl-row-text"><b>Version {v.revision}{v.revision===entry.revision?' · now':''}</b><small>{new Date(v.created_at).toLocaleString()}</small></span>{v.revision!==entry.revision&&<button type="button" disabled={disabled} onClick={()=>onRestore(JSON.parse(v.profile_json))}>Restore as draft</button>}</li>)}</ul><p className="pl-fine">Restoring makes a draft; nothing changes for agents until it is saved or updated.</p></div>;
}
function TeamBalance({team,entries,department,onChange,onGive,onOpenAgent,menu}:{team:Team|null;entries:Entry[];department:string;onChange:(a:TeamAgent)=>void;onGive:(e:Entry)=>void;onOpenAgent?:(id:string)=>void;menu:ReturnType<typeof useMenu>}){
 if(!team)return <p className="pl-empty" role="status">Team balance could not be read.</p>;
 const agents=team.agents.filter(a=>department==='all'||(a.department??'')===department);
 const cols=[{id:'thorough',title:'Thorough',hint:'checks and finishes',icon:'search' as UiIconName},{id:'balanced',title:'Balanced',hint:'a bit of both',icon:'scale' as UiIconName},{id:'inventive',title:'Inventive',hint:'new ideas',icon:'sparkle' as UiIconName}];
 const items=(a:TeamAgent):MenuItem[]=>[{label:'Change personality…',icon:'smile',disabled:a.locked,run:()=>onChange(a)},...(onOpenAgent?[{label:'Open the agent',icon:'open' as UiIconName,run:()=>onOpenAgent(a.id)}]:[])];
 return <div className="pl-balance">
  {team.gaps.map(g=>{const advice=gapAdvice[g],suggest=advice&&entries.find(e=>!e.archived&&advice.names.includes(e.profile.name));return <p key={g} className="pl-gap"><UiIcon name="bulb" size={15}/><span>{advice?.text??g}</span>{suggest&&<button type="button" className="link-button" onClick={()=>onGive(suggest)}>Give one…</button>}</p>;})}
  {!agents.length?<p className="pl-empty">No agents here.</p>:<div className="pl-cols">{cols.map(c=><section key={c.id} className="pl-col" aria-label={c.title}><h3><UiIcon name={c.icon} size={14}/>{c.title}<small>{c.hint}</small></h3><ul>{agents.filter(a=>workStyle(a.traits)===c.id).map(a=>{const e=entries.find(x=>x.id===a.personalityId);return <li key={a.id} tabIndex={0} draggable={!a.locked} title={a.locked?undefined:'Drag onto a personality in the sidebar to change it'} onDragStart={ev=>{ev.dataTransfer.setData(AGENT_DRAG,a.id);ev.dataTransfer.effectAllowed='move';}} onContextMenu={ev=>menu.at(ev,items(a))} onKeyDown={ev=>{if(ev.key==='Enter'&&!a.locked)onChange(a);if(ev.key==='ContextMenu'||ev.shiftKey&&ev.key==='F10')menu.at(ev,items(a));}} onDoubleClick={()=>{if(!a.locked)onChange(a);}}><Avatar name={a.name} size={26}/><span className="pl-row-text"><b dir="auto">{a.name}</b><small>{a.department?a.department[0].toUpperCase()+a.department.slice(1):'No department'}{a.locked?' · locked':''}</small></span>{e&&<span title={e.profile.name}><PersonalityMark profile={e.profile} size={22}/></span>}</li>;})}</ul></section>)}</div>}
  <p className="pl-fine">Drag an agent onto another personality in the sidebar, or right-click it or press Enter, to change its personality (Undo ⌘Z). This shows how agents prefer to work; it never measures skill or gives access.</p>
 </div>;
}
type Start='empty'|'copy'|'mix';
function NewSheet({entries,busy,onMake,onBlend,onClose}:{entries:Entry[];busy:boolean;onMake:(p:Profile)=>void;onBlend:(a:Profile,b:Profile,weight:number)=>void;onClose:()=>void}){
 const [start,setStart]=useState<Start>('empty'),[a,setA]=useState(entries[0]?.id??''),[b,setB]=useState(entries[1]?.id??''),[toward,setToward]=useState(40);
 const A=entries.find(e=>e.id===a),B=entries.find(e=>e.id===b);
 const make=()=>{const base=A??entries[0];if(!base)return;if(start==='empty')onMake(emptyProfile(base.profile));else if(start==='copy')onMake({...structuredClone(base.profile),name:`${base.profile.name} copy`.slice(0,80)});else if(A&&B)onBlend(A.profile,B.profile,100-toward);};
 const starts:{id:Start;title:string;text:string;icon:UiIconName}[]=[{id:'empty',title:'Start empty',text:'Every trait in the middle',icon:'file'},{id:'copy',title:'Copy one',text:'Start from a personality',icon:'copy'},{id:'mix',title:'Mix two',text:'Blend two personalities',icon:'mix'}];
 const pick=(value:string,set:(v:string)=>void,label:string,not?:string)=><select aria-label={label} value={value} onChange={e=>set(e.target.value)}>{entries.filter(e=>e.id!==not).map(e=><option key={e.id} value={e.id}>{e.profile.name}</option>)}</select>;
 return <Sheet title="New personality" wide onClose={()=>{if(!busy)onClose();}} actions={<><button type="button" disabled={busy} onClick={onClose}>Cancel</button><button type="button" className="primary" disabled={busy||!entries.length||start==='mix'&&(!A||!B||a===b)} onClick={make}>Make the draft</button></>}>
  <div className="pl-starts" role="radiogroup" aria-label="Start">{starts.map(s=><button type="button" role="radio" key={s.id} aria-checked={start===s.id} onClick={()=>setStart(s.id)}><UiIcon name={s.icon} size={18}/><b>{s.title}</b><small>{s.text}</small></button>)}</div>
  {start==='copy'&&<label className="pl-field"><span>Copy</span>{pick(a,setA,'Personality to copy')}</label>}
  {start==='mix'&&A&&B&&<div className="pl-mix"><div className="pl-mix-picks">{pick(a,setA,'First personality',b)}<UiIcon name="mix" size={16}/>{pick(b,setB,'Second personality',a)}</div><input type="range" min="0" max="100" value={toward} aria-label={`Share between ${A.profile.name} and ${B.profile.name}`} aria-valuetext={`${100-toward}% ${A.profile.name}, ${toward}% ${B.profile.name}`} onChange={e=>setToward(Number(e.target.value))}/><span className="pl-ends"><small>More {A.profile.name}</small><small>More {B.profile.name}</small></span><p className="pl-fine">{100-toward}% {A.profile.name} · {toward}% {B.profile.name}. Text follows the bigger share; guidelines from both are kept.</p></div>}
  <p className="pl-fine">It opens as a draft. Nothing is saved until you keep it.</p></Sheet>;
}
export function emptyProfile(base:Profile):Profile{return {...structuredClone(base),name:'New personality',description:'',archetype:'',strengths:'',blindSpots:'',bestFor:'',notFor:'',samples:[],traits:Object.fromEntries(Object.keys(base.traits).map(k=>[k,50])) as Profile['traits'],dialect:'en',temperament:{extraversion:50,emotionalStability:50},pace:'balanced',formality:'neutral',humour:'off',principles:{do:'',never:'',ask:''}};}

const cap=(x:string)=>x?x[0].toUpperCase()+x.slice(1):x;
/** What a linked update changes, in the editor's own words (Character, Speaking, Guidelines, About). */
export function profileChanges(before:Profile,after:Profile){
 const out:{label:string;before:string;after:string}[]=[];
 const add=(label:string,a:unknown,b:unknown)=>{if(a!==b)out.push({label,before:a===''||a==null?'Not specified':String(a),after:b===''||b==null?'Not specified':String(b)});};
 add('Name',before.name,after.name);add('In one line',before.description,after.description);
 for(const k of [...characterKeys,'verbosity'] as SliderKey[])add(sliderInfo[k].name,sliderValue(before,k),sliderValue(after,k));
 for(const [k,label] of [['pace','Pace'],['formality','Formality'],['humour','Humour']] as const)add(label,cap(before[k]),cap(after[k]));
 add('Language and dialect',dialectLabel[before.dialect as keyof typeof dialectLabel]??before.dialect,dialectLabel[after.dialect as keyof typeof dialectLabel]??after.dialect);
 for(const k of ['do','never','ask'] as const)add(guideNames[k],before.principles[k],after.principles[k]);
 for(const [k,label] of Object.entries(aboutNames))add(label,before[k as keyof typeof aboutNames],after[k as keyof typeof aboutNames]);
 add('Sounds like',cap(before.seniority),cap(after.seniority));
 add('Example replies',before.samples.join('\n'),after.samples.join('\n'));return out;
}
